"""matplotlib.style — style management.

The plotly backend doesn't honour matplotlib rc styles directly (each
plotly trace has its own theming), but we still track which style the
user requested so introspection works and any code that branches on
``matplotlib.style.library[name]`` finds the expected dict.
"""

import contextlib


# The canonical list of styles upstream ships. We track the requested
# style on a module-level variable so context managers can restore it.
available = ['default', 'classic', 'seaborn', 'ggplot', 'bmh',
             'dark_background', 'fivethirtyeight', 'grayscale',
             'fast', '_mpl-gallery', '_mpl-gallery-nogrid',
             'Solarize_Light2', 'tableau-colorblind10',
             'seaborn-v0_8', 'seaborn-v0_8-whitegrid', 'seaborn-v0_8-darkgrid',
             'seaborn-v0_8-notebook', 'seaborn-v0_8-paper',
             'seaborn-v0_8-talk', 'seaborn-v0_8-poster',
             'seaborn-v0_8-deep', 'seaborn-v0_8-pastel',
             'seaborn-v0_8-muted', 'seaborn-v0_8-bright',
             'seaborn-v0_8-colorblind', 'seaborn-v0_8-dark-palette',
             'seaborn-v0_8-dark', 'seaborn-v0_8-ticks',
             'seaborn-v0_8-white']


# Style library — each entry is a (currently empty) rcParams override
# dict. Real upstream parses .mplstyle files and populates these.
library = {name: {} for name in available}


# Currently-active style. Updated by `use()` and `context()`.
_active = ['default']


def use(style):
    """Set the active style. Accepts a single name, a list of names
    (last wins), or a dict of rcParams overrides.

    Mirrors upstream's contract: the call returns ``None`` and any
    invalid name raises :class:`OSError` (matplotlib's choice — we
    stay compatible)."""
    global _active
    if isinstance(style, dict):
        # Direct rcParams overrides — track as a unique identifier.
        from matplotlib import rcParams
        for k, v in style.items():
            try: rcParams[k] = v
            except KeyError: pass
        _active = ['<dict>']
        return
    if isinstance(style, str):
        style = [style]
    new_active = []
    for s in style:
        if s in library or s == 'default':
            new_active.append(s)
            continue
        # Try as a file path (upstream supports .mplstyle paths).
        import os
        if os.path.isfile(s):
            new_active.append(s)
            library[s] = {}  # placeholder
            continue
        raise OSError(f'{s!r} is not a known style or readable path')
    _active = new_active or ['default']


@contextlib.contextmanager
def context(style, after_reset=False):
    """Apply ``style`` for the duration of the context, then restore
    whatever was active before."""
    global _active
    saved = list(_active)
    try:
        if after_reset:
            use('default')
        use(style)
        yield
    finally:
        # Restore the previous active list (best-effort — don't pass
        # the dict path back through `use()` since we don't track it).
        _active = saved


def reload_library():
    """Re-scan for .mplstyle files. The shim doesn't read them from
    disk, so this just resets the library to the canonical defaults."""
    global library
    library = {name: {} for name in available}


def get_active():
    """Return the list of currently active style names. Not part of
    upstream's public API but useful for introspection."""
    return list(_active)
